Subroutine PrimerNegativo(a As Integer, b As Integer, c As Integer) As Integer
  If a < 0 Then
    Return a;
  EndIf
  If b < 0 Then
    Return b;
  EndIf
  Return c;
EndSubroutine

Algorithm Principal
  Write PrimerNegativo(4, -2, -7);
EndAlgorithm

Subroutine Signo(n As Integer) As String
  If n > 0 Then
    Return "positivo";
  EndIf
EndSubroutine

Algorithm Principal
  Write Signo(5);
  Write Signo(-1);
EndAlgorithm
